import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
let JSDOM,VirtualConsole;try{({JSDOM,VirtualConsole}=require(process.env.ATLAS_JSDOM||'jsdom'));}catch{({JSDOM,VirtualConsole}=require('/Users/coy/ProductSweet/Portal/node_modules/jsdom'));}
function boot(edition='index',controlledClock=false){
 let now=0,next=0;const pending=new Map();
 const advance=ms=>{now+=ms;for(const [id,t] of [...pending])if(t.at<=now){pending.delete(id);t.fn();}};
 const errors=[],vc=new VirtualConsole();vc.on('jsdomError',e=>errors.push(e.message));
 const html=readFileSync(new URL('../'+edition+'.html',import.meta.url),'utf8').replace(/<style>[\s\S]*?<\/style>/,'');
 const dom=new JSDOM(html,{url:'http://atlas.local/'+edition+'.html',runScripts:'dangerously',virtualConsole:vc,beforeParse(w){w.CSS={escape:x=>x};if(controlledClock){w.setTimeout=(fn,ms=0)=>{const id=++next;pending.set(id,{fn,at:now+ms});return id;};w.clearTimeout=id=>pending.delete(id);}}}),w=dom.window,d=w.document;
 const click=a=>{let el=[...d.querySelectorAll('[data-action]')].find(x=>x.dataset.action===a&&!x.disabled);if(!el&&/^(condition-method|condition-pay|condition-merchant|condition-lock|container-agreement|agreement-recovery):/.test(a)){d.querySelector('[data-action^="container-how:"]')?.click();el=[...d.querySelectorAll('[data-action]')].find(x=>x.dataset.action===a&&!x.disabled);}assert.ok(el,'Missing enabled action: '+a);el.click();assert.equal(d.querySelector('#toast')?.textContent?.includes('undefined'),false);};
 return {dom,w,d,click,errors,advance,text:()=>d.body.textContent};
}
function how(b){if(!b.d.querySelector('.how-sheet'))b.d.querySelector('[data-action^="container-how:"]').click();return b.d.querySelector('.how-sheet');}
for(const edition of ['index','bento','metro','workbench'])test(edition+': four moments, all tabs, view modes, modules, stories and sheets render without exceptions',()=>{const b=boot(edition);for(const id of ['alex','jordan','sam','elena']){b.click('person:'+id);for(const tab of ['now','future','you']){b.click('tab:'+tab);assert.ok(!/undefined|NaN/.test(b.d.querySelector('#content').textContent),id+' '+tab);if(tab==='future'&&b.d.querySelector('.future-beginning'))b.click('future-studio');if(tab==='future')for(const v of ['rings','area','list','bubbles']){b.click('view:'+v);b.click('time:120');assert.ok(b.d.querySelector('#future-total').textContent.includes('£'));} }for(const action of ['collection','rules','points','chat','receipts','newplan','gallery']){b.w.atlas.closeAll();if(action==='gallery')b.w.atlas.sheetAdd();else if(action==='collection')b.w.atlas.collect();else if(action==='rules'){b.click('tab:future');b.click('rules');}else if(action==='points')b.w.atlas.sheetPoints();else if(action==='chat')b.w.atlas.convo();else if(action==='receipts'){b.click('tab:now');if(id==='elena')b.w.atlas.pin('activity');b.click('receipts');}else if(action==='newplan'){b.click('tab:future');b.click('newplan');}assert.ok(b.d.querySelector('[role=dialog]'));}b.w.atlas.closeAll();b.click('tab:now');const story=b.w.ATLAS_DATA.moments[id].l2.stories[0];b.click('story:'+story.id);b.click('story-step:1');b.click('story-step:2');b.w.atlas.closeAll();for(const m of b.w.ATLAS_DATA.shared.modules.modules){b.w.atlas.preview(m.id);assert.ok(!/undefined|NaN/.test(b.d.querySelector('.sheet').textContent),m.id);b.w.atlas.closeAll();}}assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('Alex quiz → confirm → points → undo uses real event wiring',()=>{const b=boot();b.click('support:discuss');b.click('quiz');b.click('answer:0');b.click('answer:1');b.click('answer:2');b.click('quiz-finish');assert.match(b.text(),/25/);b.click('portrait');b.click('personality-confirm');assert.match(b.text(),/35/);b.click('undo');assert.match(b.d.querySelector('.points-banner').textContent,/25/);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('Jordan previews, commits a changed amount, transfers, and undoes',()=>{const b=boot();b.click('person:jordan');b.click('tab:future');b.click('idea:weat');b.click('toggle-idea:weat');assert.ok(b.d.querySelector('.preview-bar'));b.click('preview-summary');b.click('review-idea:weat');b.d.querySelector('#commit-amount').value='30';b.click('commit-idea:weat');assert.match(b.d.querySelector('.money-speed').textContent,/252/);b.w.atlas.collect();b.click('pot:ef');assert.match(b.d.querySelector('.detail-number').textContent,/430/);b.click('transfer-to:ef');b.d.querySelector('[name=amount]').value='20';b.click('transfer-review');b.click('transfer-confirm');b.w.atlas.detail('ef');assert.match(b.d.querySelector('.detail-number').textContent,/450/);b.w.atlas.closeAll();b.click('undo');b.w.atlas.detail('ef');assert.match(b.d.querySelector('.detail-number').textContent,/430/);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('Sam investment review requires acknowledgement, then debits opening cash',()=>{const b=boot();b.click('person:sam');b.click('tab:future');b.click('idea:winvest');b.click('review-idea:winvest');b.click('commit-idea:winvest');assert.match(b.d.querySelector('#toast').textContent,/Review the illustrative plan/);b.d.querySelector('#advice-agreed').checked=true;b.click('commit-idea:winvest');b.w.atlas.collect();assert.match(b.d.querySelector('.sheet').textContent,/1,820.44/);assert.match(b.d.querySelector('.sheet').textContent,/First investments/);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('Elena shared personality, beliefs, booking and permission pause',()=>{const b=boot();b.click('person:elena');b.click('tab:you');for(const m of ['aisha','leo','household']){b.click('member:'+m);assert.ok(!/undefined|NaN/.test(b.d.querySelector('.personality').textContent));}b.click('tab:now');b.click('support:discuss');b.click('appointment');b.click('book-appointment');b.click('tab:you');b.click('autonomy');b.click('pause-all');b.click('tab:future');assert.match(b.d.querySelector('.money-speed').textContent,/£0/);b.click('tab:you');b.click('autonomy');b.click('tab:future');assert.match(b.d.querySelector('.money-speed').textContent,/850/);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('presentation API supports its scripted scenes and future zoom',()=>{const b=boot();const a=b.w.atlas;assert.doesNotThrow(()=>{a.closeAll();a.go('sam','now');a.go('sam','future');a.setT(24);a.detail('house');a.back();a.go('elena','now');a.rmReset();a.convo();a.closeAll();a.go('alex','now');a.unpin('safespend');a.sheetAdd();a.preview('safespend');a.pin('safespend','L');a.edit(true);a.edit(false);a.go('sam','future');a.wif('winvest');a.closeAll();a.go('sam','me');a.go('elena','me');a.sheetStatus();a.sheetPoints();a.closeAll();});b.click('tab:future');b.click('zoom:0.25');assert.equal(b.d.querySelector('.chart-viewport').style.width,'125%');b.click('zoom:fit');assert.equal(b.d.querySelector('.chart-viewport').style.width,'100%');assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('every rendered interactive control has an accessible name',()=>{const b=boot('bento');for(const id of ['alex','jordan','sam','elena']){b.click('person:'+id);for(const tab of ['now','future','you']){b.click('tab:'+tab);for(const el of b.d.querySelectorAll('button'))assert.ok(el.getAttribute('aria-label')||el.textContent.trim(),'Unnamed control '+el.outerHTML);}}b.dom.window.close();});
test('gallery uses a shared size preview, pins the chosen size and restores it on undo',()=>{const b=boot();b.click('gallery');b.click('preview-module:safespend');b.click('preview-size:T');assert.ok(b.d.querySelector('.module-preview .module.size-T'));b.click('pin-preview:safespend');assert.ok(b.d.querySelector('#content [data-module=safespend].size-T'));b.click('undo');assert.equal(b.d.querySelector('#content [data-module=safespend]'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('Future companion responds to time and a pot can enter the shared conversation',()=>{const b=boot();b.click('person:sam');b.click('tab:future');b.click('time:24');assert.match(b.d.querySelector('.ai-card').textContent,/milestone/i);b.w.atlas.detail('house');b.click('pot-chat:house');assert.match(b.d.querySelector('.chat-thread').textContent,/House deposit has £6,400.00/);assert.match(b.d.querySelector('.chat-thread').textContent,/£320/);assert.deepEqual(b.errors,[]);b.dom.window.close();});
test('current, credit, saving, loan and investment share a container structure and contextual AI',()=>{const b=boot();for(const[person,action]of [['jordan','account:ac-cur'],['jordan','account:ac-cc'],['jordan','pot:ef'],['jordan','pot:loan'],['elena','pot:inv']]){b.click('person:'+person);b.w.atlas.collect();b.click(action);assert.deepEqual([...b.d.querySelectorAll('[data-container-section]')].map(x=>x.dataset.containerSection),['balance','actions','arrangement','activity']);assert.equal(b.d.querySelector('.pot-companion'),null);assert.ok(b.d.querySelector('#support-dock'));assert.ok(!/undefined|NaN/.test(b.d.querySelector('.container-detail').textContent));}b.click('person:jordan');b.w.atlas.collect();b.click('account:ac-cur');b.click('support:discuss');assert.match(b.d.querySelector('.chat-thread').textContent,/Safe to spend shows the estimate after those commitments/);b.w.atlas.closeAll();b.w.atlas.collect();b.click('account:ac-cc');b.click('transfer-to:ac-cc');assert.equal(b.d.querySelector('[name=to]').value,'ac-cc');assert.deepEqual(b.errors,[]);b.dom.window.close();});

function send(b,text){b.d.querySelector('#chat-input').value=text;b.d.querySelector('#chat-form').dispatchEvent(new b.w.Event('submit',{bubbles:true,cancelable:true}));}
function mockAudio(b){const stats={plays:0,pauses:0};b.w.HTMLMediaElement.prototype.play=function(){stats.plays++;Object.defineProperty(this,'paused',{value:false,configurable:true});this.dispatchEvent(new b.w.Event('play'));return Promise.resolve();};b.w.HTMLMediaElement.prototype.pause=function(){stats.pauses++;Object.defineProperty(this,'paused',{value:true,configurable:true});this.dispatchEvent(new b.w.Event('pause'));};return stats;}

test('one persistent support portal belongs to main/detail, and disappears during full-screen conversation',()=>{const b=boot();b.click('person:jordan');const dock=b.d.querySelector('#support-dock'),bar=dock.querySelector('.support-bar'),slot=dock.parentNode;b.w.atlas.detail('ef');const detail=b.d.querySelector('.sheet');assert.equal(dock.parentNode,slot);assert.equal(detail.firstElementChild.className,'sheet-header');assert.equal(detail.querySelector('#support-dock'),null);assert.equal(dock.hidden,false);assert.equal(dock.dataset.state,'compact');assert.equal(b.d.querySelector('#support-details').inert,true);assert.match(dock.textContent,/Emergency fund/);detail.querySelector('.sheet-body').scrollTop=42;b.d.querySelector('.support-bar').click();assert.match(b.d.querySelector('.chat-thread').textContent,/£570 to reach your £1,000 Emergency fund goal/);assert.equal(b.d.querySelector('.support-bar'),bar);assert.equal(dock.hidden,true);assert.equal(dock.inert,true);assert.ok(b.d.querySelector('.conversation-identity'));assert.equal(b.d.querySelector('#phone').getAttribute('aria-modal'),'true');b.click('close');assert.equal(b.d.querySelector('.sheet'),detail);assert.equal(detail.querySelector('.sheet-body').scrollTop,42);assert.equal(dock.hidden,false);assert.equal(dock.dataset.state,'compact');assert.equal(b.d.querySelector('#content').inert,true);b.click('close');assert.equal(b.d.querySelector('#content').inert,false);assert.equal(dock.parentNode,slot);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('scroll changes context without rebuilding controls, and page scrolling cannot replace an open conversation',async()=>{const b=boot(),content=b.d.querySelector('#content'),credit=b.d.querySelector('[data-module=creditscore]'),activity=b.d.querySelector('[data-module=activity]'),summary=b.d.querySelector('.support-summary');content.getBoundingClientRect=()=>({top:200,bottom:600,height:400});Object.defineProperty(content,'clientHeight',{value:400});let creditTop=220,activityTop=700;credit.getBoundingClientRect=()=>({top:creditTop,bottom:creditTop+160,height:160});activity.getBoundingClientRect=()=>({top:activityTop,bottom:activityTop+220,height:220});content.scrollTop=90;content.dispatchEvent(new b.w.Event('scroll'));await new Promise(r=>setTimeout(r,170));assert.ok(b.d.querySelector('#support-dock').classList.contains('is-compact'));assert.match(summary.textContent,/soft check/);assert.equal(summary,b.d.querySelector('.support-summary'));creditTop=-50;activityTop=220;content.dispatchEvent(new b.w.Event('scroll'));await new Promise(r=>setTimeout(r,170));assert.match(summary.textContent,/Every change/);b.click('support:discuss');assert.match(b.d.querySelector('.chat-thread').textContent,/recorded transactions/);const chatTitle=summary.textContent;content.scrollTop=0;content.dispatchEvent(new b.w.Event('scroll'));await new Promise(r=>setTimeout(r,170));assert.equal(summary.textContent,chatTitle);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('bar text opens AI even for Priya’s note, while only Premier exposes direct human access',()=>{const b=boot();for(const id of ['alex','jordan','sam']){b.click('person:'+id);b.click('support:discuss');assert.equal(b.d.querySelector('[data-action=human]'),null);assert.ok(b.d.querySelector('.chat-message:last-child').classList.contains('ai'));}b.click('person:elena');assert.match(b.d.querySelector('.support-summary').textContent,/Priya/);b.click('support:discuss');assert.match(b.d.querySelector('.chat-message.human').textContent,/Priya.*quarterly review/s);assert.ok(b.d.querySelector('.chat-message.human [data-author=priya] img'));assert.ok(b.d.querySelector('.chat-message:last-child').classList.contains('ai'));b.click('human');assert.ok(b.d.querySelector('.conversation-identity [data-author=priya] img'));send(b,'Tell me about my plans');assert.ok(b.d.querySelector('.chat-message:last-child').classList.contains('human'));b.click('support:ai');assert.ok(b.d.querySelector('.chat-message:last-child').classList.contains('ai'));assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('play avatar starts persistent bottom audio; scroll collapses support without interrupting playback',()=>{const b=boot(),stats=mockAudio(b);b.click('person:sam');assert.equal(b.d.querySelector('audio'),null);b.click('support:play');const media=b.d.querySelector('audio'),avatar=b.d.querySelector('.support-avatar'),range=b.d.querySelector('#recap-progress');assert.equal(stats.plays,1);assert.equal(b.d.querySelector('#audio-dock').hidden,false);assert.equal(b.d.querySelector('#support-dock .recap-player'),null);media.currentTime=17;media.dispatchEvent(new b.w.Event('timeupdate'));assert.equal(range,b.d.querySelector('#recap-progress'));b.d.querySelector('#content').dispatchEvent(new b.w.Event('wheel'));assert.ok(b.d.querySelector('#support-dock').classList.contains('is-compact'));assert.equal(b.d.querySelector('#support-details').inert,true);assert.equal(media.paused,false);b.click('support:play');assert.equal(stats.pauses,1);assert.ok(b.d.querySelector('#support-dock').classList.contains('is-compact'));assert.equal(b.d.querySelector('.support-avatar'),avatar);b.click('support:play');b.click('tab:future');assert.equal(b.d.querySelector('audio'),media);assert.equal(media.currentTime,17);b.click('support:back');assert.equal(media.currentTime,7);b.click('person:elena');assert.equal(stats.pauses,2);assert.equal(b.d.querySelector('audio'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('support follows story steps, idea review and a household selection',()=>{const b=boot();b.click('person:sam');b.click('story:s1');assert.match(b.d.querySelector('.support-summary').textContent,/Golden Ratio.*idea/);b.click('story-step:1');assert.match(b.d.querySelector('.support-summary').textContent,/Golden Ratio.*working/);b.click('close');b.click('tab:future');b.click('idea:winvest');assert.match(b.d.querySelector('.support-summary').textContent,/Exploring: Start investing/);b.click('person:elena');b.click('tab:you');b.click('member:aisha');assert.match(b.d.querySelector('.support-summary').textContent,/Aisha/);b.click('support:discuss');assert.match(b.d.querySelector('.chat-thread').textContent,/consent/);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('AI triages a non-Premier request before human handover; audio failure keeps the icon transcript route',()=>{const b=boot();mockAudio(b);b.click('person:jordan');b.w.atlas.detail('ef');b.click('support:discuss');send(b,'I would like a person');assert.equal(b.d.querySelector('.chat-message.human'),null);assert.match(b.d.querySelector('.chat-message:last-child').textContent,/What would you like help/);send(b,'My emergency fund contributions');assert.match(b.d.querySelector('.chat-thread').textContent,/context we were exploring: £570/);assert.match(b.d.querySelector('.support-summary').textContent,/Maya/);b.click('person:sam');b.click('support:play');b.d.querySelector('audio').dispatchEvent(new b.w.Event('error'));assert.match(b.d.querySelector('.recap-player').textContent,/Audio unavailable/);b.click('support:transcript');assert.match(b.d.querySelector('.sheet-body').textContent,/Hi Sam/);assert.equal(b.d.querySelector('.recap-snapshot'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('system workbench and blueprint expose the same production review states',()=>{for(const edition of ['workbench','support-blueprint']){const b=boot(edition);mockAudio(b);for(const state of ['expanded','compact','detail','conversation','priya','maya','audio','playing','detached','paused','ended','error']){b.click('support-case:'+state);assert.ok(b.d.querySelector('#support-diagnostics').textContent.includes('header'));assert.equal(b.d.querySelectorAll('#support-dock').length,1);if(state==='priya'){assert.equal(b.d.querySelectorAll('.support-actions button').length,2);assert.ok(b.d.querySelector('.support-avatar img').src.startsWith('data:image/jpeg;base64,'));}if(state==='maya'){assert.ok(b.d.querySelector('.conversation-identity [data-author=maya] img'));assert.match(b.d.querySelector('#support-diagnostics').textContent,/Maya/);}if(state==='error'){assert.match(b.d.querySelector('.recap-error').textContent,/unavailable/);b.click('support:transcript');assert.match(b.d.querySelector('.sheet-body').textContent,/Hi Sam/);}}assert.deepEqual(b.errors,[]);b.dom.window.close();}});
test('expanded CTAs hide on attention to content; conversation uses a consistent vendored AI identity',()=>{const b=boot('index',true);b.advance(2000);const details=b.d.querySelector('#support-details');assert.equal(details.inert,false);assert.ok(details.querySelector('[data-action=quiz]'));b.d.querySelector('#content').dispatchEvent(new b.w.Event('wheel'));assert.equal(details.inert,true);b.click('support:discuss');assert.equal(b.d.querySelector('#support-dock').hidden,true);for(const el of b.d.querySelectorAll('[data-author=ai] svg'))assert.equal(el.dataset.material,'auto_awesome');assert.ok(b.d.querySelector('.conversation-identity'));assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('details start compact without audio offers; ongoing audio stays in its independent player',()=>{const b=boot();mockAudio(b);b.click('person:sam');b.click('support:play');const audio=b.d.querySelector('audio');b.click('module:grocery');assert.equal(audio.paused,false);assert.equal(b.d.querySelector('#audio-dock').hidden,false);assert.equal(b.d.querySelector('.support-avatar').dataset.action,'support:discuss');assert.equal(b.d.querySelector('#support-dock').dataset.state,'compact');assert.match(b.d.querySelector('.support-message').textContent,/spent on groceries/);b.click('support:play');assert.equal(audio.paused,true);b.click('support:stop');assert.equal(b.d.querySelector('#audio-dock').hidden,true);assert.equal(b.d.querySelector('audio'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('main headers scroll away and top restores initial support on all three tabs; details stay fixed',()=>{const b=boot();for(const tab of ['now','future','you']){b.click('tab:'+tab);assert.equal(b.d.querySelector('.app-header [data-action="support:discuss"]'),null);const content=b.d.querySelector('#content'),phone=b.d.querySelector('#phone');content.scrollTop=120;content.dispatchEvent(new b.w.Event('scroll'));assert.equal(phone.style.getPropertyValue('--header-scroll'),'58px');assert.equal(b.d.querySelector('.app-header').inert,true);assert.equal(b.d.querySelector('#support-dock').dataset.state,'compact');content.scrollTop=0;content.dispatchEvent(new b.w.Event('scroll'));assert.equal(phone.style.getPropertyValue('--header-scroll'),'0px');assert.equal(b.d.querySelector('.app-header').inert,false);assert.equal(b.d.querySelector('#support-dock').dataset.state,tab==='you'?'compact':'expanded');assert.equal(b.d.querySelector('#support-details').inert,tab==='you');}b.click('tab:now');b.w.atlas.preview('grocery');const detail=b.d.querySelector('.sheet-body');detail.scrollTop=120;detail.dispatchEvent(new b.w.Event('scroll'));assert.equal(b.d.querySelector('#phone').style.getPropertyValue('--header-scroll'),'0px');detail.scrollTop=0;detail.dispatchEvent(new b.w.Event('scroll'));assert.equal(b.d.querySelector('#support-dock').dataset.state,'compact');assert.ok(b.d.querySelector('.sheet-header'));assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('trailing upward wheel and touch-end events cannot leave the top card minimised',async()=>{const b=boot(),content=b.d.querySelector('#content');content.scrollTop=130;content.dispatchEvent(new b.w.Event('scroll'));content.scrollTop=0;content.dispatchEvent(new b.w.Event('scroll'));for(let i=0;i<3;i++)content.dispatchEvent(new b.w.WheelEvent('wheel',{deltaY:-25}));assert.equal(b.d.querySelector('#support-dock').dataset.state,'expanded');content.dispatchEvent(new b.w.Event('touchmove'));content.dispatchEvent(new b.w.Event('touchend'));await new Promise(r=>setTimeout(r,150));assert.equal(b.d.querySelector('#support-dock').dataset.state,'expanded');assert.deepEqual(b.errors,[]);b.dom.window.close();});
