test('Now thinking lasts two seconds, yields to intent, and never leaks into other screens',()=>{
 const b=boot('index',true),state=()=>b.d.querySelector('#support-dock').dataset.state;
 assert.equal(state(),'thinking');assert.equal(b.d.querySelector('#support-details').inert,true);
 b.advance(1999);assert.equal(state(),'thinking');b.advance(1);assert.equal(state(),'expanded');assert.equal(b.d.querySelector('#support-details').inert,false);
 b.click('person:sam');assert.equal(state(),'thinking');assert.equal(b.d.querySelector('.support-avatar').dataset.action,'support:discuss');b.advance(2000);assert.equal(b.d.querySelector('.support-avatar').dataset.action,'support:play');
 b.click('tab:future');assert.equal(state(),'expanded');b.click('tab:now');assert.equal(state(),'thinking');b.click('tab:you');b.advance(2500);assert.equal(state(),'compact');assert.doesNotMatch(b.d.querySelector('.support-summary').textContent,/Thinking/);
 b.click('tab:now');assert.equal(state(),'thinking');const content=b.d.querySelector('#content');content.scrollTop=130;content.dispatchEvent(new b.w.Event('scroll'));assert.equal(state(),'compact');b.advance(2500);assert.equal(state(),'compact');content.scrollTop=0;content.dispatchEvent(new b.w.Event('scroll'));assert.equal(state(),'expanded');
 b.click('reset');assert.equal(state(),'thinking');b.click('support:discuss');b.advance(2500);assert.equal(b.d.querySelector('#support-dock').hidden,true);assert.doesNotMatch(b.d.querySelector('.chat-thread').textContent,/Thinking/);
 b.click('close');b.click('reset');b.click('module:grocery');b.advance(2500);assert.equal(state(),'compact');
 b.click('person:elena');assert.equal(state(),'expanded');assert.ok(b.d.querySelector('.support-avatar img'));assert.deepEqual(b.errors,[]);b.dom.window.close();
});

test('journey CTA owns its header; AI help preserves quiz step and form drafts',()=>{
 const b=boot('index',true);b.advance(2000);
 b.d.querySelector('.support-actions [data-action=quiz]').click();
 const journey=()=>{assert.equal(b.d.querySelector('#phone').dataset.supportSurface,'journey');assert.equal(b.d.querySelector('#support-dock').hidden,true);assert.ok(b.d.querySelector('.sheet-header .journey-help'));assert.ok(b.d.querySelector('.sheet.support-journey'));};
 journey();assert.match(b.d.querySelector('.sheet-header').textContent,/Getting to know you/);
 b.click('answer:0');const question=b.d.querySelector('.quiz-question').textContent,step=b.d.querySelector('.sheet-body');step.scrollTop=55;
 b.d.querySelector('.journey-help').click();assert.match(b.d.querySelector('.chat-thread').textContent,/question 2/);assert.ok(b.d.querySelector('.chat-thread').textContent.includes(question));b.click('close');journey();assert.equal(b.d.querySelector('.sheet-body'),step);assert.equal(step.scrollTop,55);assert.equal(b.d.querySelector('.quiz-question').textContent,question);assert.equal(b.d.activeElement,b.d.querySelector('.journey-help'));
 b.click('answer:1');b.click('answer:2');journey();assert.ok(b.d.querySelector('[data-action=quiz-finish]'));b.click('quiz-finish');assert.equal(b.d.querySelector('#phone').dataset.supportSurface,'main');
 b.click('tab:now');b.click('transfer');journey();const form=b.d.querySelector('#transfer-form'),amount=form.querySelector('[name=amount]');amount.value='12';b.d.querySelector('.journey-help').click();b.click('close');journey();assert.equal(b.d.querySelector('#transfer-form'),form);assert.equal(amount.value,'12');
 b.click('close');b.click('person:jordan');b.w.atlas.pin('grocery');b.click('module:grocery');assert.equal(b.d.querySelector('#phone').dataset.supportSurface,'detail');assert.equal(b.d.querySelector('#support-dock').hidden,false);assert.equal(b.d.querySelector('.journey-help'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();
});

test('Now numbers share one grid; first number can resize, move, remove and be restored',()=>{
 const b=boot();assert.equal(b.d.querySelector('.lead-number'),null);assert.match(b.d.querySelector('.now-page').textContent,/My numbers/);
 const nodes=[...b.d.querySelector('.now-page').children];assert.ok(nodes.findIndex(n=>n.matches('.quick-actions'))<nodes.findIndex(n=>n.matches('.pots-entry')));assert.ok(nodes.findIndex(n=>n.matches('.module-grid'))<nodes.findIndex(n=>n.matches('.pots-entry')));assert.ok(nodes.findIndex(n=>n.matches('.pots-entry'))<nodes.findIndex(n=>n.matches('.stories')));assert.ok(nodes.findIndex(n=>n.matches('.stories'))<nodes.findIndex(n=>n.matches('.products-entry')));
 assert.ok(b.d.querySelector('.module-grid [data-module=container-ac-cur].size-W'));b.click('customise');b.click('size:container-ac-cur');assert.ok(b.d.querySelector('.module-grid [data-module=container-ac-cur].size-T'));b.click('up:dd');assert.equal(b.d.querySelector('.module-grid [data-module]').dataset.module,'dd');b.click('remove:container-ac-cur');assert.equal(b.d.querySelector('.module-grid [data-module=container-ac-cur]'),null);b.click('undo');assert.ok(b.d.querySelector('.module-grid [data-module=container-ac-cur].size-T'));assert.deepEqual(b.errors,[]);b.dom.window.close();
});
test('shortcut editor saves replacements, supports removal, cancellation, per-person preferences and undo',()=>{
 const b=boot();const primary=()=>[...b.d.querySelectorAll('#content .quick-actions button')].map(x=>x.textContent.trim());
 b.click('quick-more');b.click('quick-edit');b.click('quick-select:statements');b.click('quick-select:pay');b.click('quick-done');assert.deepEqual(primary(),['Statements','Transfer','Add money','More']);
 b.click('quick-more');b.click('quick-edit');b.click('quick-select:transfer');b.click('quick-place:available');assert.equal(b.d.querySelectorAll('.primary-actions [data-shortcut]').length,2);b.click('close');assert.deepEqual(primary(),['Statements','Transfer','Add money','More']);
 b.click('person:sam');assert.deepEqual(primary(),['Pay','Transfer','Add money','More']);b.click('person:alex');assert.equal(primary()[0],'Statements');b.click('receipts');b.click('undo');assert.equal(primary()[0],'Pay');assert.deepEqual(b.errors,[]);b.dom.window.close();
});
