test('accounts collection connects chosen sample accounts, reconciles its count and disconnects without changing HSBC money',()=>{
 const b=boot();const count=()=>b.d.querySelector('.pots-entry').textContent;const beforeCount=Number(count().match(/\d+/)[0]);const beforeBalance=b.d.querySelector('[data-module=container-ac-cur] .module-value').textContent;
 b.click('collection');assert.match(b.d.querySelector('.support-message').textContent,/Connect accounts/);assert.ok(b.d.querySelector('.connect-entry [data-action=connect-bank]'));
 b.click('connect-bank');assert.equal(b.d.querySelector('#support-dock').hidden,true);b.click('connect-review:monzo');b.click('connect-confirm:monzo');assert.equal(b.d.querySelector('#connection-error').hidden,false);b.d.querySelector('#connection-form input[value=current]').checked=true;b.click('connect-confirm:monzo');
 assert.equal(Number(count().match(/\d+/)[0]),beforeCount+1);assert.equal(b.d.querySelectorAll('.other-banks .holding-row').length,1);assert.equal(b.d.querySelector('[data-module=container-ac-cur] .module-value').textContent,beforeBalance);assert.match(b.d.querySelector('.overview-footnote').textContent,/845.60/);assert.match(b.d.querySelector('.support-message').textContent,/845.60/);
 b.click('connected-account:monzo/current');b.click('disconnect-review:monzo');b.click('disconnect-confirm:monzo');assert.equal(Number(count().match(/\d+/)[0]),beforeCount);assert.equal(b.d.querySelectorAll('.other-banks .holding-row').length,0);assert.equal(b.d.querySelector('[data-module=container-ac-cur] .module-value').textContent,beforeBalance);b.click('undo');assert.equal(Number(count().match(/\d+/)[0]),beforeCount+1);assert.deepEqual(b.errors,[]);b.dom.window.close();
});
