test('Sam and Elena start with distinct connected banks and reset restores their sample picture',()=>{
 const b=boot();for(const [person,count,external,total] of [['sam',12,2,'£100,345.60'],['elena',9,3,'£307,701.05']]){
 b.click('person:'+person);assert.match(b.d.querySelector('.pots-entry').textContent,new RegExp('· '+count));b.click('collection');assert.equal(b.d.querySelectorAll('.other-banks .holding-row').length,external);assert.equal(b.d.querySelector('.overview-value').textContent,total);assert.ok(b.d.querySelector('[data-bank=hsbc] img').src.startsWith('data:image/'));for(const img of b.d.querySelectorAll('.other-banks .bank-avatar img'))assert.ok(img.src.startsWith('data:image/'));
 const bank=person==='sam'?'monzo':'natwest';b.click('connected-account:'+bank+'/current');b.click('disconnect-review:'+bank);b.click('disconnect-confirm:'+bank);b.click('connect-bank');b.click('connect-review:'+bank);assert.match(b.d.querySelector('.consent-accounts').textContent,person==='sam'?/845.60/:/3,840.80/);b.w.atlas.closeAll();b.click('reset');b.click('collection');assert.equal(b.d.querySelector('.overview-value').textContent,total);b.w.atlas.closeAll();
 }assert.deepEqual(b.errors,[]);b.dom.window.close();
});

test('five container variants follow the supplied IA; wallet rules require review and update the same Number',()=>{const b=boot('workbench');for(const id of ['budget','savings','loan','investment','shared']){b.click('bench-container:'+id);assert.deepEqual([...b.d.querySelectorAll('[data-container-section]')].map(x=>x.dataset.containerSection),['balance','actions','arrangement','activity']);assert.equal(b.d.querySelector('.sheet-header').textContent.includes('undefined'),false);assert.equal(b.d.querySelector('#support-dock').dataset.state,'compact');assert.equal(b.d.querySelectorAll('.container-system').length,1);assert.ok(!/undefined|NaN|\[object Object\]/.test(b.d.querySelector('.container-system').textContent));}b.click('bench-container:budget');b.click('container-more:budget');b.click('container-rule-new:budget');assert.equal(b.d.querySelector('#support-dock').hidden,true);b.d.querySelector('[name=amount]').value='220';b.d.querySelector('[name=limitMonthly]').value='220';b.d.querySelector('[name=reserve]').value='500';b.click('container-rule-review:budget');assert.match(b.d.querySelector('.sheet-body').textContent,/Money moved now£0/);b.click('container-rule-save');b.click('condition-method:budget/funding');assert.equal(b.d.querySelectorAll('.container-rule').length,1);const rule=b.d.querySelector('.container-rule').dataset.action;b.click(rule);b.click(rule.replace('container-rule:','container-rule-toggle:'));b.click('container-rule-confirm');b.click('condition-method:budget/funding');assert.match(b.d.querySelector('.container-rule .status-chip').textContent,/Paused/);b.w.atlas.closeAll();b.w.atlas.detail('budget');b.click('container-info:budget');b.click('preview-module:container-budget');b.click('preview-size:W');b.click('pin-preview:container-budget');assert.ok(b.d.querySelector('#content [data-module=container-budget].size-W'));assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('editing a payment changes fulfilment while cancellation and rate are preserved',()=>{const b=boot('workbench');b.click('bench-container:savings');b.click('condition-method:house/contribution');b.click('container-rule:r-house-payday');b.click('container-rule-edit:r-house-payday');b.d.querySelector('[name=amount]').value='100';b.click('container-rule-review:house');assert.match(b.d.querySelector('.method-overview').textContent,/£220.*manually/);b.click('close');b.w.atlas.closeAll();b.w.atlas.detail('house');assert.match(how(b).querySelector('[data-condition=contribution]').textContent,/Planned/);b.click('condition-method:house/contribution');b.click('container-rule:r-house-payday');b.click('container-rule-edit:r-house-payday');b.d.querySelector('[name=amount]').value='100';b.click('container-rule-review:house');b.click('container-rule-save');assert.match(how(b).querySelector('[data-condition=contribution]').textContent,/£220.*yourself/);assert.match(b.d.querySelector('.arrangement-benefit').textContent,/5.1%/);assert.deepEqual(b.errors,[]);b.dom.window.close();});

test('sharing waits for explicit demo acceptance; evolution keeps amount, identity, and updates the widget',()=>{const b=boot('workbench');b.click('bench-container:budget');b.click('container-more:budget');b.click('container-members:budget');b.d.querySelector('#container-invite-form [name=name]').value='Taylor';b.click('container-invite-review:budget');b.click('container-invite-save');assert.match(b.d.querySelector('.container-invitation').textContent,/waiting for acceptance/);b.click('container-accept:invite-0');assert.match(b.d.querySelector('.container-members').textContent,/Taylor/);b.click('bench-container:savings');b.click('container-more:house');b.click('container-evolve:house');b.click('container-evolve-confirm:house');assert.ok(b.d.querySelector('#container-risk-agreed'));b.d.querySelector('#container-risk-agreed').checked=true;b.click('container-evolve-confirm:house');assert.equal(b.d.querySelector('.container-system').dataset.containerType,'investment');assert.match(b.d.querySelector('.detail-number').textContent,/6,400/);assert.match(b.d.querySelector('#content [data-module=housepot]').textContent,/fall/);assert.equal(how(b).querySelectorAll('.container-rule').length,1);assert.deepEqual(b.errors,[]);b.dom.window.close();});

