test('agreement bottom sheet preserves the underlying pot, scroll, context and focus',()=>{const b=boot();b.click('person:elena');b.w.atlas.detail('fam');const sheet=b.d.querySelector('.sheet'),body=sheet.querySelector('.sheet-body'),card=b.d.querySelector('[data-action="container-how:fam"]'),message=b.d.querySelector('.support-message').textContent;body.scrollTop=160;card.focus();b.click('container-how:fam');b.click('container-agreement:fam');assert.match(b.d.querySelector('.agreement-sheet').textContent,/4.5% AER variable/);assert.match(b.d.querySelector('.agreement-sheet').textContent,/Each member/);assert.equal(b.d.querySelector('#overlay').inert,true);assert.equal(b.d.querySelector('.sheet'),sheet);b.d.dispatchEvent(new b.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal(b.d.querySelector('#agreement-layer'),null);assert.equal(b.d.querySelector('#overlay').inert,false);assert.equal(body.scrollTop,160);assert.equal(b.d.activeElement,card);assert.equal(b.d.querySelector('.support-message').textContent,message);b.click('container-agreement:fam');b.d.querySelector('.agreement-scrim').click();assert.equal(b.d.querySelector('#agreement-layer'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();});

