test('credit More offers repayment and applicable actions; cancelling edits preserves shortcuts',()=>{
 const b=boot();b.click('person:jordan');b.click('account:ac-cc');b.click('container-more:ac-cc');
 assert.match(b.d.querySelector('.shortcut-editor').textContent,/On this account/);assert.ok(b.d.querySelector('[data-action="transfer-to:ac-cc"]'));assert.equal(b.d.querySelector('[data-action="transfer-from:ac-cc"]'),null);assert.equal(b.d.querySelector('[data-action="container-members:ac-cc"]'),null);
 b.click('quick-edit');b.click('quick-select:rule');b.click('quick-select:info');b.w.atlas.closeAll();b.click('account:ac-cc');
 assert.ok(b.d.querySelector('.container-actions [data-action="container-info:ac-cc"]'));assert.equal(b.d.querySelector('.container-actions [data-action="container-rule-new:ac-cc"]'),null);assert.deepEqual(b.errors,[]);b.dom.window.close();
});

test('how sheet terms and follow-up task return preserve overview scroll with one sheet',()=>{
 const b=boot();b.click('person:sam');b.w.atlas.detail('house');b.click('container-how:house');
 b.d.querySelector('.agreement-sheet-body').scrollTop=120;b.click('container-agreement:house');assert.equal(b.d.querySelectorAll('#agreement-layer').length,1);assert.ok(b.d.querySelector('.agreement-full'));
 b.click('container-how:house');assert.equal(b.d.querySelector('.agreement-sheet-body').scrollTop,120);assert.equal(b.d.querySelector('.how-sheet details'),null);
 b.click('condition-method:house/contribution');assert.equal(b.d.querySelector('#agreement-layer'),null);assert.ok(b.d.querySelector('.method-overview'));b.click('close');assert.ok(b.d.querySelector('.how-sheet'));assert.equal(b.d.querySelector('.agreement-sheet-body').scrollTop,120);
 b.click('agreement-close');assert.equal(b.d.querySelector('#agreement-layer'),null);assert.equal(b.d.querySelector('#overlay').inert,false);assert.deepEqual(b.errors,[]);b.dom.window.close();
});
